def is_not_prime(n):
    """Return True if n is a non-prime number, False if n is prime."""
    if n < 2:
        return True
    if n < 4:
        return False  # 2 and 3 are prime
    if n % 2 == 0 or n % 3 == 0:
        return True
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return True
        i += 6
    return False

