def is_sublist(lst, sub):
    """Check whether the list `lst` contains `sub` as a contiguous sublist."""
    n, m = len(lst), len(sub)
    if m == 0:
        return True
    return any(lst[i:i + m] == sub for i in range(n - m + 1))


