    assert is_sublist([2, 4, 3, 5, 7], [3, 7]) == False
    assert is_sublist([2, 4, 3, 5, 7], [4, 3]) == True
    assert is_sublist([2, 4, 3, 5, 7], [2, 4, 3, 5, 7]) == True
    assert is_sublist([2, 4, 3, 5, 7], [1]) == False
    assert is_sublist([1, 2, 3], []) == True
    print("All tests passed.")

def is_samepatterns(colors, patterns):
    """Check whether the strings in `colors` follow the sequence given in `patterns`.

    Two sequences follow the same pattern if there is a one-to-one (bijective)
    mapping between elements of `colors` and elements of `patterns` such that
    each occurrence of a color maps to the same pattern element, and each
    pattern element maps back to the same color.

    >>> is_samepatterns(["red","green","green"], ["a", "b", "b"])
    True
    """
    if len(colors) != len(patterns):
        return False

    color_to_pattern = {}
    pattern_to_color = {}

    for color, pattern in zip(colors, patterns):
        if color in color_to_pattern:
            if color_to_pattern[color] != pattern:
                return False
        else:
            color_to_pattern[color] = pattern

        if pattern in pattern_to_color:
            if pattern_to_color[pattern] != color:
                return False
        else:
            pattern_to_color[pattern] = color

    return True

