def amicable_numbers_sum(limit):
    """Sum all amicable numbers from 1 to limit (inclusive).

    Two distinct numbers a and b are amicable if the sum of the proper
    divisors of a equals b and the sum of the proper divisors of b equals a.
    """
    if not isinstance(limit, int) or limit < 1:
        return 0

    def sum_proper_divisors(n):
        if n <= 1:
            return 0
        total = 1  # 1 is always a proper divisor of n > 1
        i = 2
        while i * i <= n:
            if n % i == 0:
                total += i
                other = n // i
                if other != i:
                    total += other
            i += 1
        return total

    total = 0
    for a in range(1, limit + 1):
        b = sum_proper_divisors(a)
        if b != a and sum_proper_divisors(b) == a:
            total += a
    return total


if __name__ == "__main__":
    assert amicable_numbers_sum(999) == 504
    assert amicable_numbers_sum(300) == 504
    assert amicable_numbers_sum(219) == 0
    assert amicable_numbers_sum(1) == 0
    print("All tests passed.")

import cmath


def angle_complex(a, b):
    """Return the angle (phase, in radians) of a complex number.

    The complex number is formed from the two arguments:
    - if ``b`` is already a complex number (e.g. ``1j``), the number is ``a + b``,
      so ``angle_complex(0, 1j)`` gives the angle of ``1j`` (i.e. pi/2);
    - otherwise ``a`` and ``b`` are the real and imaginary parts, i.e. the
      number is ``complex(a, b)``.
    """
    if isinstance(b, complex):
        c = a + b
    else:
        c = complex(a, b)
    return cmath.phase(c)

