import math


def zero_count(nums):
    """Return the ratio of zeroes to non-zeroes in a list of integers."""
    zeroes = sum(1 for x in nums if x == 0)
    non_zeroes = len(nums) - zeroes
    if non_zeroes == 0:
        return float('inf') if zeroes else float('nan')
    return zeroes / non_zeroes


if __name__ == "__main__":
    assert math.isclose(zero_count([0, 1, 2, -1, -5, 6, 0, -3, -2, 3, 4, 6, 8]), 0.181818, rel_tol=0.001)
    print("All tests passed.")

def extract_singly(test_list):
    """Flatten a list of lists (or tuples) into a single set of numbers."""
    res = set()
    for sub in test_list:
        for ele in sub:
