def find_even_pair(nums):
    """Count pairs (i, j) with i < j such that nums[i] ^ nums[j] is even.

    XOR of two integers is even exactly when both have the same parity
    (their least significant bits match).
    """
    count = 0
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if (nums[i] ^ nums[j]) % 2 == 0:
                count += 1
    return count


