def max_sum(arr):
    """Return the maximum sum of a bitonic subsequence of arr.

    A bitonic subsequence is first strictly increasing and then strictly
    decreasing. For each index i we compute:
      - msis[i]: max sum of an increasing subsequence ending at i
      - msds[i]: max sum of a decreasing subsequence starting at i
    The best bitonic subsequence peaks at some i, so the answer is
    max(msis[i] + msds[i] - arr[i]).
    """
    n = len(arr)
    if n == 0:
        return 0

    # Maximum sum of increasing subsequence ending at each index.
    msis = list(arr)
    for i in range(1, n):
        for j in range(i):
            if arr[j] < arr[i] and msis[j] + arr[i] > msis[i]:
                msis[i] = msis[j] + arr[i]

    # Maximum sum of decreasing subsequence starting at each index.
    msds = list(arr)
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            if arr[j] < arr[i] and msds[j] + arr[i] > msds[i]:
                msds[i] = msds[j] + arr[i]

    return max(msis[i] + msds[i] - arr[i] for i in range(n))


