def division_elements(tuple1, tuple2):
    """Perform element-wise division across two tuples.

    Each element of `tuple1` is divided by the corresponding element of
    `tuple2`. Results that are whole numbers are returned as ints;
    fractional results are returned as floats.

    >>> division_elements((10, 4, 6, 9), (5, 2, 3, 3))
    (2, 2, 2, 3)
    """
    result = []
    for a, b in zip(tuple1, tuple2):
        quotient = a / b
        if quotient == int(quotient):
            result.append(int(quotient))
        else:
            result.append(quotient)
    return tuple(result)


