def all_unique(lst):
    """Check if all elements of the given list are unique.

    Returns True if no element appears more than once, False otherwise.
    Works with unhashable elements (e.g., lists) via a fallback comparison.
    """
    try:
        return len(set(lst)) == len(lst)
    except TypeError:
        # Fallback for unhashable elements
        seen = []
        for item in lst:
            if item in seen:
                return False
            seen.append(item)
        return True


