    assert all_unique([1, 2, 3]) == True
    assert all_unique([1, 2, 2]) == False
    assert all_unique([]) == True
    assert all_unique(['a', 'b', 'a']) == False
    assert all_unique([[1], [2]]) == True
    assert all_unique([[1], [1]]) == False
    print("All tests passed.")

