def max_Product(arr):
    """Find the pair of elements in arr whose product is the highest.

    Returns the pair as a tuple in the order the elements appear in arr.
    Returns None if the array has fewer than two elements.
    """
    arr_len = len(arr)
    if arr_len < 2:
        return None

    x = arr[0]
    y = arr[1]

    for i in range(arr_len):
        for j in range(i + 1, arr_len):
            if arr[i] * arr[j] > x * y:
                x = arr[i]
                y = arr[j]

    return x, y

