def extract_even(test_tuple):
    """Remove odd (uneven) elements from a nested mixed tuple, recursively.

    Nested tuples are preserved (even if they become empty); only odd
    numbers are dropped.

    >>> extract_even((4, 5, (7, 6, (2, 4)), 6, 8))
    (4, (6, (2, 4)), 6, 8)
    """
    res = []
    for ele in test_tuple:
        if isinstance(ele, tuple):
            res.append(extract_even(ele))
        elif isinstance(ele, int) and ele % 2 == 0:
            res.append(ele)
    return tuple(res)

