def largest_subset(nums):
    """
    Find the size of the largest subset of a list of numbers such that
    every pair of elements in the subset is divisible
    (i.e., for any pair (a, b), either a % b == 0 or b % a == 0).
    """
    if not nums:
        return 0

    nums = sorted(nums)
    n = len(nums)
    # dp[i] = size of the largest divisible subset ending at index i
    dp = [1] * n

    for i in range(n):
        for j in range(i):
            if nums[i] % nums[j] == 0:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)


