def jacobsthal_num(n):
    """Find the nth Jacobsthal number (0-indexed).

    Sequence: 0, 1, 1, 3, 5, 11, 21, 43, 85, 171, 341, 683, 1365, 2731, ...
    Recurrence: J(n) = J(n-1) + 2*J(n-2), with J(0) = 0, J(1) = 1.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 0
    if n == 1:
        return 1
    prev, curr = 0, 1
    for _ in range(2, n + 1):
        prev, curr = curr, curr + 2 * prev
    return curr


if __name__ == "__main__":
    assert jacobsthal_num(5) == 11
    assert [jacobsthal_num(i) for i in range(14)] == [
        0, 1, 1, 3, 5, 11, 21, 43, 85, 171, 341, 683, 1365, 2731
    ]
    print("All tests passed.")

