def check_expression(exp):
    """Check whether the brackets in the given expression are balanced."""
    if len(exp) & 1:
        return False
    pairs = {')': '(', '}': '{', ']': '['}
    stack = []
    for char in exp:
        if char in '({[':
            stack.append(char)
        elif char in ')}]':
            if not stack or stack.pop() != pairs[char]:
                return False
    return not stack


if __name__ == "__main__":
    assert check_expression("{()}[{}]") == True
    assert check_expression("{()}[{]}") == False
    assert check_expression("{()}[{}]()") == True
    assert check_expression("{()") == False
    assert check_expression("()") == True
    assert check_expression("(") == False
    assert check_expression(")(") == False
    assert check_expression("") == True
    print("All tests passed.")

def occurance_substring(text, pattern):
    """Find the occurrence and position of a substring within a string.

    Returns a tuple (substring, start_index, end_index) for the first
    occurrence of `pattern` in `text`, where end_index is exclusive.
    Returns None if there is no match.
    """
    index = text.find(pattern)
    if index == -1:
        return None
    return (text[index:index + len(pattern)], index, index + len(pattern))

