def sum_in_range(l, r):
    """Return the sum of all odd natural numbers within the range [l, r]."""
    # First odd number >= l
    first = l if l % 2 == 1 else l + 1
    # Last odd number <= r
    last = r if r % 2 == 1 else r - 1
    if first > last:
        return 0
    # Number of odd terms in [first, last]
    count = (last - first) // 2 + 1
    # Arithmetic series sum
    return count * (first + last) // 2


if __name__ == "__main__":
    assert sum_in_range(2, 5) == 8
    # Brute-force cross-check
    def brute(l, r):
        return sum(n for n in range(l, r + 1) if n % 2 == 1)

    for l in range(0, 30):
        for r in range(l, 30):
            assert sum_in_range(l, r) == brute(l, r), (l, r)
    print("All tests passed.")

